code_example:
std::vector<int> data = {1, 2, 3};
size_t index = 5;

try {
    int value = data.at(index);
}
catch (const std::out_of_range& e) {
    // Handle invalid index access
    std::cerr << "Error: " << e.what() << std::endl;
}

// Also thrown by std::string::substr with bad length
std::string s = "abc";
s.substr(0, 5); // Throws std::out_of_range
// ... handled similarly
// std::deque, std::map::at() also throw this.
